// TH15 v1.00b. Source: st02.ecl.txt:925-949 MainSub00, dependencies GirlA01 (8-24),
// GirlA01_at (26-64), GirlRedA01e/GirlBlueA01e (748-756/293-301).
// Card frame 0 = source MainSub00 entry; 120-frame shell buffer covers the opening.
const TIME_LIMIT: int = 1624;
const OPENING_BUFFER: int = 120;
const TH15_RICE: int = 480;

// GirlA01_at: wait 40+RAND%140, then one fixed 5-way ring with 6 speed layers
// (etAim mode3, etAngle pi/2/0, etSpeed 3.5..1.0 step -0.5). EX type 2 is the
// birth ANIM: animation stage omitted (approved), but its 4*speed retreat at
// birth is kept; firing per layer lets sh_dist carry each layer's own speed.
async sub girl_attack() {
    wait(40 + rand(140));
    var rank: int = global(GVAR_RANK);
    var ways: int = 5;
    var layers: int = 6;
    var speed0: fx = 3.5fx;
    if rank == 0 { ways = 3; layers = 1; speed0 = 1.5fx; }
    else if rank == 1 { ways = 3; layers = 2; speed0 = 1.5fx; }
    else if rank == 2 { ways = 5; layers = 4; speed0 = 2.5fx; }
    sh_reset(0);
    sh_sprite(0, TH15_RICE, 6);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_angle(0, 90deg, 0deg);
    for q in 0..layers {
        var speed: fx = speed0 - (q as fx) * 0.5fx;
        sh_count(0, ways, 1);
        sh_speed(0, speed, 0fx);
        sh_dist(0, 0fx - 4fx * speed); // ANIM birth retreat: position -= 4*velocity
        sh_fire(0);
    }
}

// GirlA01 movement. Source moveVel(67.5deg,2) then moveVelTime(60,0,22.5deg,3)
// and moveVelTime(60,0,45deg,2), then the endless wait loop. The mirrored
// create variant (enmCreateM) reflects the x axis: angle -> 180deg-angle.
async sub girl(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx); // setHurtbox(24,24): circular branch radius = 24*0.5
    set_hitbox(8fx);   // setHitbox(16,16): circular branch radius = 16*0.5
    spawn girl_attack();
    var a0: angle = 67.5deg;
    var a1: angle = 22.5deg;
    var a2: angle = 45deg;
    if mirror != 0 {
        a0 = 112.5deg;
        a1 = 157.5deg;
        a2 = 135deg;
    }
    move_vel(0, a0, 2fx, EASE_LINEAR);
    wait(30);
    move_vel(60, a1, 3fx, EASE_LINEAR);
    wait(60);
    move_vel(60, a2, 2fx, EASE_LINEAR);
    wait(60);
    loop { wait(1000); }
}

// One source side: 10 pairs, red at y=-16 then blue at y=-28, 10 frames apart,
// 20 frames per pair (200 frames per side).
sub spawn_side(x: fx, mirror: int) {
    var n: int = 10;
    loop {
        _ = spawn_enemy(x, -16fx, 100, 0, 0, 0, girl(mirror));
        wait(10);
        _ = spawn_enemy(x, -28fx, 100, 0, 0, 0, girl(mirror));
        wait(10);
        n = n - 1;
        if n <= 0 { return; }
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    spawn_side(192fx, 1);  // enmCreateM at +192, sub mirror 1
    spawn_side(-192fx, 0); // enmCreate at -192
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
